        } else {
            null
        }
    }

    /**
     * Constructs schedule URL with date parameter
     */
    fun buildScheduleUrl(baseUrl: String, formattedDate: String): String {
        val argumentsRegex = Regex("ARGUMENTS=([^&]+)")
