        val existingArguments = existingArgumentsMatch?.groupValues?.get(1) ?: ""

        val updatedArguments = existingArguments.replaceFirst("-A", "-A$formattedDate")

        return baseUrl.replace(existingArguments, updatedArguments).replace(
