package de.fampopprol.dhbwhorb.ui.screen.settingsScreen.generalSettingsSection
import androidx.compose.foundation.clickable import androidx.compose.foundation.layout.Arrangement import androidx.compose.foundation.layout.Column import androidx.compose.foundation.layout.fillMaxWidth import androidx.compose.foundation.layout.padding import androidx.compose.material.icons.Icons import androidx.compose.material.icons.filled.DarkMode import androidx.compose.material.icons.filled.LightMode import androidx.compose.material.icons.filled.Palette import androidx.compose.material3.Card import androidx.compose.material3.CardDefaults import androidx.compose.material3.Icon import androidx.compose.material3.MaterialTheme import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.res.stringResource import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.unit.dp import de.fampopprol.dhbwhorb.R import de.fampopprol.dhbwhorb.ui.theme.ThemeMode
@Composable fun ThemeModeButton( themeMode: ThemeMode, isSelected: Boolean, onClick: () -> Unit, modifier: Modifier = Modifier ) { Card( modifier = modifier .fillMaxWidth() .clickable { onClick() }, colors = CardDefaults.cardColors( containerColor = if (isSelected) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant ) ) { Column( modifier = Modifier .fillMaxWidth() .padding(12.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(4.dp) ) { Icon( imageVector = when (themeMode) { ThemeMode.LIGHT -> Icons.Default.LightMode ThemeMode.DARK -> Icons.Default.DarkMode ThemeMode.SYSTEM -> Icons.Default.Palette }, contentDescription = null, tint = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurfaceVariant ) Text( text = stringResource( when (themeMode) { ThemeMode.LIGHT -> R.string.theme_light ThemeMode.DARK -> R.string.theme_dark ThemeMode.SYSTEM -> R.string.theme_system } ), style = MaterialTheme.typography.bodySmall, fontWeight = if (isSelected) FontWeight.SemiBold else FontWeight.Normal, color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurfaceVariant ) } } }

